import { setContext, getContext } from "svelte";
import type { FieldErrorItem } from "#lib/components/ui/field/index.js";

const CONTEXT_ID = "form-field-context";

class UseFieldCtx {
	/** Dotted path of the value */
	name = $state("");
	/** Unique prefix for the control, description, and error ids */
	baseId = $state("");
	/** Whether a `FormDescription` is mounted to describe the control */
	hasDescription = $state(false);
	/** Reads the field's shown errors */
	getErrors: () => FieldErrorItem[] = () => [];
	/** Marks the field as visited */
	touch: () => void = () => {};

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}

	/** Id of the control, referenced by the label's `for` */
	get controlId() {
		return `${this.baseId}-control`;
	}

	/** Id of the description */
	get descriptionId() {
		return `${this.baseId}-description`;
	}

	/** Id of the error message */
	get errorId() {
		return `${this.baseId}-error`;
	}

	/** Errors shown for the field */
	get errors() {
		return this.getErrors();
	}

	/** Ids that describe the control: the description, and the errors while there are any */
	get describedBy() {
		const ids = [this.hasDescription && this.descriptionId, this.errors.length > 0 && this.errorId].filter(Boolean);
		return ids.length ? ids.join(" ") : undefined;
	}
}

export type FieldCtxProps = Pick<InstanceType<typeof UseFieldCtx>, "name" | "baseId" | "getErrors" | "touch">;

export const setFieldCtx = (props: FieldCtxProps) => setContext(CONTEXT_ID, new UseFieldCtx(props));

export const useFieldCtx = () => getContext<ReturnType<typeof setFieldCtx>>(CONTEXT_ID);

import type { z } from "zod";
import type { FormState } from "./state.svelte.js";
import type { FieldProps } from "#lib/components/ui/field/index.js";

export { default as Form } from "./_.svelte";
export { default as FormField } from "./field.svelte";
export { default as FormControl } from "./control.svelte";
export { default as FormLabel } from "./label.svelte";
export { default as FormDescription } from "./description.svelte";
export { default as FormFieldErrors } from "./errors.svelte";
export { createForm, FormState } from "./state.svelte.js";

/** Options for `createForm` */
export interface FormOptions<S extends z.ZodType> {
	/** Values the form starts with; also used by `reset` */
	initial: z.input<S>;
	/** Called with the parsed values when a valid form is submitted; without it, a valid form submits natively */
	onSubmit?: (data: z.output<S>, e: SubmitEvent) => unknown;
}

/** Form element wired to the state; blocks invalid submits */
export interface Props<S extends z.ZodType> extends CompPropsWithChild<"form"> {
	/** State from `createForm` */
	form: FormState<S>;
	/** Classes merged onto the form */
	class?: CompPropsWithChild<"form">["class"];
}

/** One form field; a `Field` that knows its name, ids, and errors */
export interface FieldItemProps<S extends z.ZodType> extends FieldProps {
	/** State from `createForm` */
	form: FormState<S>;
	/** Dotted path of the value, such as `email` or `address.city` */
	name: string;
}

/** Attributes to spread onto the field's control */
export interface ControlAttrs {
	/** Id the label points at */
	id: string;
	/** Name the form submits the value under */
	name: string;
	/** Shows the invalid ring while the field has errors */
	"aria-invalid": boolean | undefined;
	/** Ids of the description and the errors */
	"aria-describedby": string | undefined;
	/** Marks the field as visited when focus leaves it, so its errors show */
	onblur: () => void;
}

/** Hands the control attributes to its child */
export interface ControlProps {
	/** Renders the control; spread `props` onto it */
	children: Snippet<[{ props: ControlAttrs }]>;
}

export type FormProps<S extends z.ZodType> = Props<S>;
export type FormFieldProps<S extends z.ZodType> = FieldItemProps<S>;
export type FormControlProps = ControlProps;

import { tick } from "svelte";
import type { z } from "zod";
import type { FieldErrorItem } from "#lib/components/ui/field/index.js";
import type { FormOptions } from "./index.js";

/** Values, validation, and submission for a form checked by a zod schema */
export class FormState<S extends z.ZodType> {
	/** Current values; bind controls to its fields, such as `bind:value={form.values.email}` */
	values: z.input<S>;
	/** Fields the user has left at least once, by name */
	touched: Record<string, boolean> = $state({});
	/** Whether the user has tried to submit, which shows every error */
	submitted = $state(false);
	/** Whether `onSubmit` is running */
	submitting = $state(false);
	/** Schema the values are checked against */
	#schema: S;
	/** Values the form started with, for `reset` */
	#initial: z.input<S>;
	/** Called with the parsed values when a valid form is submitted */
	#onSubmit: FormOptions<S>["onSubmit"];

	/** Result of checking the current values */
	result = $derived.by(() => this.#schema.safeParse(this.values));
	/** Every error message, by dotted field path; form-level errors use an empty path */
	errors: Record<string, FieldErrorItem[]> = $derived.by(() => {
		const errors: Record<string, FieldErrorItem[]> = {};
		for (const issue of this.result.error?.issues ?? []) {
			const path = issue.path.map(String).join(".");
			(errors[path] ??= []).push({ message: issue.message });
		}
		return errors;
	});
	/** Whether the current values pass the schema */
	isValid = $derived.by(() => this.result.success);

	constructor(schema: S, options: FormOptions<S>) {
		this.#schema = schema;
		this.#initial = options.initial;
		this.#onSubmit = options.onSubmit;
		// Deep state, so binding to a nested field updates the validation.
		this.values = $state(structuredClone(options.initial));
	}

	/** Returns a field's errors once the user has left it or tried to submit; none before that. */
	errorsFor(name: string) {
		return this.submitted || this.touched[name] ? (this.errors[name] ?? []) : [];
	}

	/** Marks a field as visited, so its errors show. */
	touch(name: string) {
		this.touched[name] = true;
	}

	/** Restores the starting values, or new ones, and hides every error. */
	reset(values: z.input<S> = this.#initial) {
		this.values = structuredClone(values);
		this.touched = {};
		this.submitted = false;
	}

	/** Checks the values on submit: blocks an invalid submit, calls `onSubmit` when set, or lets the browser submit. */
	submit = async (e: SubmitEvent & { currentTarget: HTMLFormElement }) => {
		// Read the form now, since the event's current target is cleared after the first await.
		const formEl = e.currentTarget;
		this.submitted = true;
		const result = this.result;
		// If the values fail the schema: stop the submit and move focus to the first invalid control.
		if (!result.success) {
			e.preventDefault();
			await tick();
			formEl.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();
			return;
		}
		// If there is no submit handler: let the browser submit, such as to a SvelteKit form action.
		if (!this.#onSubmit) return;
		e.preventDefault();
		this.submitting = true;
		try {
			await this.#onSubmit(result.data, e);
		} finally {
			this.submitting = false;
		}
	};
}

/** Creates the state for a form checked by a zod schema. */
export function createForm<S extends z.ZodType>(schema: S, options: FormOptions<S>) {
	return new FormState(schema, options);
}
